BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats3-q01', '推測統計',
   '先生はクラス40人全員の身長を測ってグラフにまとめた。一方、研究者は全国の中学生から400人だけを選んで身長を測り、そこから「全国の中学生の平均身長」を見積もろうとした。研究者がしている作業を何と呼ぶ？',
   NULL::text,
   '["推測統計", "記述統計", "仮説検定", "相関分析"]',
   0, '[0]', 'single',
   '{"asked": "手元のデータをまとめる作業と、一部から全体を推し量る作業の呼び分け。", "point": "手元にある分だけをまとめるなら記述統計。一部のデータから、まだ見ていない全体を推し量るなら推測統計。", "kid": "統計には大きく2つの仕事がある。手元に集めたデータをそのまま整理してグラフや平均にまとめる「記述統計」と、手元の一部のデータだけから、まだ調べていない全体の姿を言い当てる「推測統計」。", "eg": "クラス全員の身長を測って表にするのは、教室にある荷物を並べて写真を撮るようなもの。400人だけ測って全国の姿を言い当てるのは、みそ汁をひとさじだけ味見して鍋全体の味を言い当てるようなもの。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"170\" y1=\"14\" x2=\"170\" y2=\"140\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"88\" y=\"26\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">記述統計</text><text x=\"88\" y=\"42\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">手元をまとめる</text><text x=\"88\" y=\"64\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">42 58 61 73</text><line x1=\"88\" y1=\"74\" x2=\"88\" y2=\"94\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"88,94 85.4,89.7 90.6,89.7\" fill=\"#3b82f6\"/><text x=\"88\" y=\"112\" fill=\"#6ab08d\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">平均 58.5</text><text x=\"88\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">合計・平均でまとめる</text><text x=\"254\" y=\"26\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">推測統計</text><text x=\"254\" y=\"42\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">一部から全体を推し量る</text><circle cx=\"228\" cy=\"76\" r=\"13\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"228\" y=\"79\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">標本</text><line x1=\"244\" y1=\"76\" x2=\"268\" y2=\"76\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"268,76 263.7,78.6 263.7,73.4\" fill=\"#3b82f6\"/><circle cx=\"292\" cy=\"76\" r=\"20\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"292\" y=\"80\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">母集団</text><text x=\"254\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">少数から全体を言い当てる</text></svg>", "terms": [["記述統計", "手元にあるデータをそのまま整理してまとめる統計"], ["推測統計", "手元の一部のデータから、まだ見ていない全体を推し量る統計"], ["母集団", "本当に知りたい対象の全体。この例では全国の中学生全員"]], "think": "先生は40人「全員」を測っているので、まとめるだけで答えが出る。これが記述統計。研究者は全国の中学生「全員」を測ってはいない。400人という一部のデータしか手元にないのに、そこから「全国の中学生全員」の平均を言い当てようとしている。手元にないものを、手元にある一部から推し量る作業だから、これは推測統計と呼ばれる。", "vs": "記述統計は手元にあるものをまとめるだけで完結する。推測統計は手元にない全体まで話を広げる点が違う。全国調査のニュースで見る「〜割の人が」という数字は、たいてい一部の調査から全体を推し量った推測統計の結果。", "why_asked": "世の中の多くの数字は、全員を調べ尽くすことができずに一部からの推測で作られている。その推測がどれくらい信じてよいかを扱うのが、この先に習う標準誤差や信頼区間で、その入り口がこの2つの呼び分け。", "usecase": "内閣支持率調査（数千人から日本全体を推し量る）、新薬の効果検証（一部の患者から全患者への効果を推し量る）。ニュースで見る「〜割の人が」という数字はほぼ全部これ。", "opt": ["正解。手元にある400人のデータから、まだ調べていない全国の中学生全員の姿を推し量っているので推測統計。", "記述統計は先生がしたように、手元にある分だけをそのまままとめる作業。全体を推し量る話にはならない。", "仮説検定は差や効果が本当にあると言えるかを判断する手法で、平均を推し量る作業そのものではない。", "相関分析は2つの量の関係の強さを調べる手法で、1つの量の平均を全体について推し量る話とは別物。"]}'),

  ('stats3-q02', '推測統計',
   '一人暮らしのユウは大きな鍋いっぱいのみそ汁を作り、味を確かめるためにお玉でひとさじだけすくって味見した。この時、鍋の中身全体に対応する統計の言葉はどれ？',
   NULL::text,
   '["母集団", "標本", "標本誤差", "標準誤差"]',
   0, '[0]', 'single',
   '{"asked": "本当に知りたい対象の全体と、そこから取り出した一部の呼び名。", "point": "知りたい対象の全体が母集団。そこから実際に取り出して調べる一部が標本。鍋全体が母集団、お玉ひとさじが標本。", "kid": "母集団は「本当に知りたい、全部」のこと。標本は「実際に手に取って調べる、一部」のこと。鍋いっぱいのみそ汁が母集団、お玉ですくった一杯が標本。", "eg": "鍋を混ぜてから味見するのは、まさに統計の標本調査そのもの。鍋の中身（母集団）を全部飲み干さなくても、よく混ぜたひとさじ（標本）を味見すれば、鍋全体の味がだいたい分かる。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><circle cx=\"95\" cy=\"68\" r=\"42\" fill=\"#3b82f6\" opacity=\"0.14\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"95\" y=\"64\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">母集団</text><text x=\"95\" y=\"82\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">鍋の中身 全部</text><path d=\"M140 68 Q185 40 222 66\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\" stroke-dasharray=\"3 3\"/><line x1=\"222\" y1=\"66\" x2=\"236\" y2=\"68\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"236,68 231.4,69.9 232.1,64.8\" fill=\"#60a5fa\"/><text x=\"180\" y=\"34\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\">すくう</text><circle cx=\"255\" cy=\"70\" r=\"17\" fill=\"#60a5fa\" opacity=\"0.28\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"255\" y=\"74\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">標本</text><text x=\"255\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">お玉ひとさじ</text><text x=\"170\" y=\"134\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">全部飲まなくても、一部の味で鍋全体が分かる</text></svg>", "terms": [["母集団", "本当に知りたい対象の全体。この例では鍋いっぱいのみそ汁"], ["標本", "母集団から実際に取り出して調べる一部。この例ではお玉ひとさじ"], ["標本調査", "標本だけを調べて、母集団の姿を推し量る調査のやり方"]], "think": "鍋を全部飲んで確かめれば確実だが、時間もお腹もかかって現実的ではない。よく混ぜたあとなら、ひとさじの味は鍋全体の味とほぼ同じになるはずだという考え方に乗っかって、ひとさじ（標本）から鍋全体（母集団）の味を判断する。この「一部から全体を判断する」発想が推測統計の土台になる。", "vs": "母集団と標本は「全体」と「一部」の関係であって、良い悪いの話ではない。ただしひとさじの取り方が偏る（鍋の底の具ばかりすくうなど）と、鍋全体の味を正しく代表しなくなる点には注意がいる。", "why_asked": "全国の有権者・全患者・全製品のように、母集団を全部調べるのは時間もお金もかかりすぎて無理なことが多い。そこで一部（標本）だけ調べて全体を言い当てる、という発想そのものがこの先ずっと出てくる土台の言葉。", "usecase": "世論調査（有権者全体が母集団、電話をかけた数千人が標本）、工場の抜き取り検査（製品全部が母集団、抜き取った数十個が標本）。", "opt": ["正解。鍋の中身全部が、本当に知りたい対象の全体、つまり母集団。", "お玉ですくったひとさじが標本。母集団から取り出した一部のこと。", "標本誤差は、標本ごとに味見の結果が少しずつ違うこと。鍋の中身そのものの呼び名ではない。", "標準誤差は、標本の結果がどれくらいばらつくかを表す数字。鍋の中身そのものの呼び名ではない。"]}'),

  ('stats3-q03', '推測統計',
   '国勢調査は日本に住む人全員を対象に調べる。一方でテレビの視聴率調査は、全世帯のうちごく一部の世帯だけに機械を置いて調べる。視聴率調査のような、一部だけを調べるやり方を何と呼ぶ？',
   NULL::text,
   '["標本調査", "全数調査", "無作為抽出", "標本誤差"]',
   0, '[0]', 'single',
   '{"asked": "対象を全部調べるやり方と、一部だけ調べるやり方の呼び分け。", "point": "対象を漏れなく全部調べるのが全数調査。一部だけを調べて全体を推し量るのが標本調査。", "kid": "調べ方には2通りある。国勢調査のように対象全員を1人残らず調べる「全数調査」と、視聴率調査のように一部だけを調べて全体の様子を推し量る「標本調査」。", "eg": "クラス全員のテストの平均を出すのに、40人全員の答案を採点するのが全数調査。時間がなくて5人だけ採点して「だいたいこれくらいだろう」と見積もるのが標本調査。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"80\" y=\"18\" fill=\"#e8eaf0\" font-size=\"11.5\" text-anchor=\"middle\" font-weight=\"600\">全数調査</text><text x=\"80\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">全員を1人残らず調べる</text><rect x=\"40\" y=\"44\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"64\" y=\"44\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"88\" y=\"44\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"40\" y=\"66\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"64\" y=\"66\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"88\" y=\"66\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"40\" y=\"88\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"64\" y=\"88\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"88\" y=\"88\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"80\" y=\"138\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">例：国勢調査</text><text x=\"258\" y=\"18\" fill=\"#e8eaf0\" font-size=\"11.5\" text-anchor=\"middle\" font-weight=\"600\">標本調査</text><text x=\"258\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">一部だけ調べて全体を推し量る</text><rect x=\"218\" y=\"44\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"242\" y=\"44\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#2a2f3f\" opacity=\"1\"/><rect x=\"266\" y=\"44\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#2a2f3f\" opacity=\"1\"/><rect x=\"218\" y=\"66\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#2a2f3f\" opacity=\"1\"/><rect x=\"242\" y=\"66\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"266\" y=\"66\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#2a2f3f\" opacity=\"1\"/><rect x=\"218\" y=\"88\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#2a2f3f\" opacity=\"1\"/><rect x=\"242\" y=\"88\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#2a2f3f\" opacity=\"1\"/><rect x=\"266\" y=\"88\" width=\"17\" height=\"17\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"258\" y=\"138\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">例：視聴率調査</text><line x1=\"188\" y1=\"10\" x2=\"188\" y2=\"140\" stroke=\"#2a2f3f\" stroke-width=\"1\"/></svg>", "terms": [["全数調査", "対象の全員・全部を漏れなく調べる調査"], ["標本調査", "対象の一部だけを調べて、全体の様子を推し量る調査"], ["国勢調査", "日本に住む人全員を対象にする、全数調査の代表例"]], "think": "全数調査は正確だが、対象が数千万人・数億台となると、時間もお金も膨大にかかり、そもそも間に合わないことも多い。視聴率のように「今この瞬間、日本中で何が見られているか」を知りたいときに全数調査を待っていては手遅れになる。そこで一部の世帯だけを継続して調べ、そこから全体を推し量る標本調査が使われる。", "vs": "全数調査は漏れなく正確だが時間とコストが大きい。標本調査は速くて安いが、一部から推し量るぶんの誤差（標本誤差）が生まれる。どちらが優れているかではなく、目的に応じた使い分け。", "why_asked": "国の重要な決定（選挙区割りなど）には全数調査、日々変わる数字（視聴率・支持率）には標本調査、というように使い分けの理由を知らないと、両方とも同じ「アンケート」とひとくくりにして誤解してしまう。", "usecase": "国勢調査（全数調査、5年に1度）、視聴率調査・世論調査・出口調査（標本調査、日常的に実施）。", "opt": ["正解。視聴率調査は全世帯のうち一部だけを調べて全体を推し量る、標本調査の代表例。", "全数調査は国勢調査のように対象全員を漏れなく調べるやり方で、一部だけを調べる視聴率調査とは逆になる。", "無作為抽出は標本を選ぶときの偏りのない選び方のことで、調査の種類そのものの名前ではない。", "標本誤差は標本調査をするたびに結果が少しずつずれること。調査のやり方そのものの名前ではない。"]}'),

  ('stats3-q04', '推測統計',
   'クラス40人から5人を選んでアンケートを取りたい。「教卓の近くに座っている5人」を選ぶやり方と、「くじを引いて出た番号の5人」を選ぶやり方では、どちらが偏りのない選び方と言える？',
   NULL::text,
   '["くじを引いて選ぶやり方", "教卓の近くの5人を選ぶやり方", "成績上位5人を選ぶやり方", "声をかけやすい友達5人を選ぶやり方"]',
   0, '[0]', 'single',
   '{"asked": "標本を選ぶときに、偏りを生まない選び方の名前。", "point": "全員に選ばれる確率が同じになるように、くじやサイコロのような偶然の力で選ぶのが無作為抽出。", "kid": "無作為抽出は、母集団の中の誰もが同じ確率で選ばれるように、くじ引きのような偶然の仕組みで標本を選ぶこと。選ぶ人の好みや都合を一切入れない。", "eg": "福引きで箱の中に手を入れて1枚引くのが無作為抽出のイメージ。「当たりが入っていそうな場所を探って引く」のは無作為ではない。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"84\" y=\"18\" fill=\"#c47070\" font-size=\"11.5\" text-anchor=\"middle\" font-weight=\"600\">偏った選び方</text><text x=\"84\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">仲のいい友達にだけ聞く</text><circle cx=\"30\" cy=\"50\" r=\"6\" fill=\"#3b82f6\"/><circle cx=\"52\" cy=\"50\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"74\" cy=\"50\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"96\" cy=\"50\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"30\" cy=\"70\" r=\"6\" fill=\"#3b82f6\"/><circle cx=\"52\" cy=\"70\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"74\" cy=\"70\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"96\" cy=\"70\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"30\" cy=\"90\" r=\"6\" fill=\"#3b82f6\"/><circle cx=\"52\" cy=\"90\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"74\" cy=\"90\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"96\" cy=\"90\" r=\"6\" fill=\"#2a2f3f\"/><text x=\"84\" y=\"128\" fill=\"#c47070\" font-size=\"9.5\" text-anchor=\"middle\">選ばれる人がかたよる</text><text x=\"262\" y=\"18\" fill=\"#6ab08d\" font-size=\"11.5\" text-anchor=\"middle\" font-weight=\"600\">無作為抽出</text><text x=\"262\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">くじ引きで選ぶ</text><circle cx=\"208\" cy=\"50\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"230\" cy=\"50\" r=\"6\" fill=\"#3b82f6\"/><circle cx=\"252\" cy=\"50\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"274\" cy=\"50\" r=\"6\" fill=\"#3b82f6\"/><circle cx=\"208\" cy=\"70\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"230\" cy=\"70\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"252\" cy=\"70\" r=\"6\" fill=\"#3b82f6\"/><circle cx=\"274\" cy=\"70\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"208\" cy=\"90\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"230\" cy=\"90\" r=\"6\" fill=\"#3b82f6\"/><circle cx=\"252\" cy=\"90\" r=\"6\" fill=\"#2a2f3f\"/><circle cx=\"274\" cy=\"90\" r=\"6\" fill=\"#2a2f3f\"/><text x=\"262\" y=\"128\" fill=\"#6ab08d\" font-size=\"9.5\" text-anchor=\"middle\">全員に平等にチャンスがある</text><line x1=\"190\" y1=\"10\" x2=\"190\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1\"/></svg>", "terms": [["無作為抽出", "母集団の全員が同じ確率で選ばれるように、偶然の仕組みで標本を選ぶこと"], ["偏り（バイアス）", "選び方が特定のグループに寄ってしまい、全体を正しく代表できなくなること"]], "think": "教卓の近くの5人には「積極的な性格」など何かしら共通点が混ざりやすく、クラス全体の意見を正しく代表しない恐れがある。声をかけやすい友達も同じで、意見が似た人ばかり集まりやすい。くじで選べば、選ぶ側の意図が一切入らないので、成績も性格も座席もばらばらな5人が集まりやすくなる。これが標本を母集団の縮図に近づける方法。", "vs": "無作為抽出は選ぶ手続きの話で、標本調査は一部だけ調べるというやり方そのものの話。標本調査であっても、選び方が偏っていれば、その結果は信用できなくなる。", "why_asked": "標本から母集団を推し量る計算（この先の標準誤差や信頼区間）は、標本が偏りなく選ばれていることを前提にした計算。選び方が偏っていると、どれだけ立派な計算をしても答えそのものが最初から間違っている。", "usecase": "世論調査での電話番号のランダム発信、臨床試験での患者のランダムな割り付け、品質検査でのロット内からのランダムな抜き取り。", "opt": ["正解。くじで選べば全員が同じ確率で選ばれ、選ぶ側の意図や偏りが入らない。", "教卓の近くの5人は座席という共通点で選ばれており、クラス全体の縮図とは限らない。", "成績上位5人は成績という条件で選ばれた特定のグループで、クラス全体を代表する選び方ではない。", "声をかけやすい友達は、選ぶ人の交友関係という都合で選ばれており、意見が似た人に偏りやすい。"]}'),

  ('stats3-q05', '推測統計',
   '同じ鍋のみそ汁を、3回に分けてそれぞれ別のお玉でひとさじずつ味見した。塩加減の感じ方が3回とも少しずつ違った。鍋の味自体は変わっていないのに、味見のたびに結果が少しずつ違うこの現象を何と呼ぶ？',
   NULL::text,
   '["標本誤差", "標準偏差", "偏差値", "外れ値"]',
   0, '[0]', 'single',
   '{"asked": "同じ母集団から標本を取り直すたびに、結果が少しずつ違ってしまう現象の名前。", "point": "母集団は同じでも、標本の中身が毎回少しだけ違うので、標本から計算した値も毎回少しずれる。このずれが標本誤差。", "kid": "標本誤差は、同じ鍋（同じ母集団）から、すくうたび（標本を取るたび）に、味見の結果（標本の値）が自然に少しずつずれてしまうこと。鍋が変わったわけでも、誰かが失敗したわけでもない、標本を使う以上どうしても生まれるずれ。", "eg": "同じ袋のくじを3回引き直したら、出てくる当たりの数が毎回少し違うのと同じ。袋の中身（母集団）は変わっていないのに、たまたま手に取った数枚（標本）が毎回違うから。", "viz": "<svg viewBox=\"0 0 340 144\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"30\" y1=\"90\" x2=\"310\" y2=\"90\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"170\" y1=\"24\" x2=\"170\" y2=\"90\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><text x=\"170\" y=\"16\" fill=\"#c9a04a\" font-size=\"9.5\" text-anchor=\"middle\">真の値（鍋全体の本当の濃さ）</text><circle cx=\"95\" cy=\"72\" r=\"5\" fill=\"#60a5fa\"/><text x=\"95\" y=\"100\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">標本1</text><circle cx=\"130\" cy=\"72\" r=\"5\" fill=\"#60a5fa\"/><text x=\"130\" y=\"100\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">標本2</text><circle cx=\"210\" cy=\"72\" r=\"5\" fill=\"#60a5fa\"/><text x=\"210\" y=\"100\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">標本3</text><circle cx=\"245\" cy=\"72\" r=\"5\" fill=\"#60a5fa\"/><text x=\"245\" y=\"100\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">標本4</text><text x=\"170\" y=\"128\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">鍋の味は同じでも、すくうたびに味見の結果は少しずれる</text></svg>", "terms": [["標本誤差", "標本ごとの結果が母集団の真の値からずれてしまう、標本調査に自然につきまとうずれ"], ["真の値", "母集団そのものが持っている、本当の平均や割合"]], "think": "お玉ひとさじの中に、たまたま濃いところの汁が多く入るか、薄いところの汁が多く入るかは、すくうたびに変わる。これは味見をした人の腕の良し悪しではなく、鍋の中身が完全に均一ではない以上、標本を取れば必ず起きるゆらぎ。だから1回の味見の結果だけを鵜呑みにせず、標本誤差というゆらぎが乗っていることを前提に結果を見る必要がある。", "vs": "標準偏差は、1つの標本や母集団の中でのデータのばらつきを表す言葉。標本誤差は、標本そのものを取り直すたびに生まれる標本平均のずれを指し、比べている対象が違う。", "why_asked": "標本調査の結果には必ずこのずれが乗っていることを知らないと、今回の1回の調査結果が絶対の真実だと誤解してしまう。この先の標準誤差や信頼区間は、この標本誤差の大きさを数字で表すための道具。", "usecase": "選挙前の世論調査で、同じ時期でも調査会社によって支持率が数%違って出る理由の説明。何度か調査してばらつきの幅を確かめる、という発想の土台。", "opt": ["正解。同じ母集団からでも、標本を取り直すたびに結果が少しずつずれること。", "標準偏差は、1回の標本や母集団の中でのデータの散らばりの大きさを表す数字で、味見のたびのずれとは別の話。", "偏差値は平均を50に換算した位置を表す数字で、標本を取り直すたびのずれとは関係がない。", "外れ値は仲間から極端に離れた1つの値のことで、標本ごとの結果のずれ全体を指す言葉ではない。"]}'),

  ('stats3-q06', '推測統計',
   '同じ鍋から、ひとさじだけ味見するのを100回繰り返した場合と、お玉10杯ぶんをまとめて味見するのを100回繰り返した場合とでは、どちらの100回の結果のほうがばらつきが小さいと考えられる？',
   NULL::text,
   '["お玉10杯ぶんをまとめて味見したほう", "ひとさじだけ味見したほう", "どちらも同じばらつきになる", "鍋の大きさによって決まり、すくう量とは関係ない"]',
   0, '[0]', 'single',
   '{"asked": "標本の大きさ（すくう量・人数）と、標本平均のばらつきの関係。", "point": "標本を大きくするほど、標本平均のばらつき（標準誤差）は小さくなる。標準誤差は標準偏差を標本の大きさの平方根で割った値。", "kid": "標準誤差は、標本平均が母集団の真の値からどれくらいばらつきやすいかを表す数字。標本を大きくするほど、この数字は小さくなり、標本平均は真の値に近づきやすくなる。", "eg": "ひとさじだけだと、濃いところ・薄いところの運に結果が大きく左右される。お玉10杯ぶんを混ぜて味見すれば、濃い部分と薄い部分がならされて、鍋全体の本当の味に近づく。すくう量が多いほど、たまたまの運の影響が薄まる。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"200\" y1=\"18\" x2=\"200\" y2=\"132\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 2\"/><text x=\"200\" y=\"12\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">母集団の真の値</text><text x=\"18\" y=\"40\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">n=10</text><line x1=\"90\" y1=\"46\" x2=\"310\" y2=\"46\" stroke=\"#8892a4\" stroke-width=\"2.4\"/><line x1=\"90\" y1=\"40\" x2=\"90\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.4\"/><line x1=\"310\" y1=\"40\" x2=\"310\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.4\"/><text x=\"318\" y=\"50\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">大</text><text x=\"18\" y=\"80\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">n=100</text><line x1=\"130\" y1=\"86\" x2=\"270\" y2=\"86\" stroke=\"#60a5fa\" stroke-width=\"2.4\"/><line x1=\"130\" y1=\"80\" x2=\"130\" y2=\"92\" stroke=\"#60a5fa\" stroke-width=\"1.4\"/><line x1=\"270\" y1=\"80\" x2=\"270\" y2=\"92\" stroke=\"#60a5fa\" stroke-width=\"1.4\"/><text x=\"278\" y=\"90\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">中</text><text x=\"18\" y=\"120\" fill=\"#3b82f6\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">n=1000</text><line x1=\"165\" y1=\"126\" x2=\"235\" y2=\"126\" stroke=\"#3b82f6\" stroke-width=\"2.4\"/><line x1=\"165\" y1=\"120\" x2=\"165\" y2=\"132\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><line x1=\"235\" y1=\"120\" x2=\"235\" y2=\"132\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><text x=\"243\" y=\"130\" fill=\"#3b82f6\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">小</text><text x=\"200\" y=\"145\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">すくう量(n)が増えるほど、標本平均の散らばりは狭くなる</text></svg>", "terms": [["標準誤差", "標本平均が母集団の真の値からどれくらいばらつきやすいかを表す数字。標準偏差を標本の大きさの平方根で割った値"], ["標本の大きさ（n）", "1回の標本調査で集めたデータの個数。この例ではすくう量や調べる人数"]], "think": "標準誤差は、母集団の標準偏差を標本の大きさ（n）の平方根で割った値として計算される。割る数である√nが大きくなるほど、割り算の答えである標準誤差は小さくなる。ひとさじ（小さいn）よりお玉10杯ぶん（大きいn）のほうがnが大きいので、√nも大きくなり、標準誤差は小さくなる。だから標本が大きいほど、標本平均は真の値のまわりに小さくばらつくようになる。", "vs": "標準偏差は、1つの標本の中の個々のデータのばらつき（みそ汁の濃い薄いそのもの）。標準誤差は、標本平均というまとめた1つの数字が標本ごとにどれだけばらつくかを表す、別のレベルの数字。", "why_asked": "調査の人数を増やすと結果が安定する、という直感を数式で裏付けるのが標準誤差。次に習う信頼区間の幅の広さも、この標準誤差の大きさで決まる。", "usecase": "世論調査で「サンプル数が多いほど信頼できる」と言われる理由の説明。実験計画で必要な最低限の人数（サンプルサイズ）を決めるときの計算の土台。", "opt": ["正解。すくう量（標本の大きさ）が多いほど、たまたまの偏りがならされて、標本平均のばらつき（標準誤差）は小さくなる。", "ひとさじだけのほうがすくう量が少なく、濃い薄いの運の影響を受けやすいので、100回の結果はむしろばらつきやすい。", "標準誤差は標本の大きさによって変わる数字で、すくう量が違えば結果のばらつき方も変わってしまう。", "標準誤差の大きさは標本の大きさに左右されるので、すくう量と無関係ということはない。"]}'),

  ('stats3-q07', '推測統計',
   'アンケートの結果から「日本人の平均睡眠時間はちょうど6.5時間」と1つの数字で言う言い方と、「日本人の平均睡眠時間はだいたい6.2〜6.8時間の間」と幅で言う言い方がある。後者のような、幅を持たせた言い方を何と呼ぶ？',
   NULL::text,
   '["区間推定", "点推定", "標準誤差", "標本誤差"]',
   0, '[0]', 'single',
   '{"asked": "母集団の値を、1つの数字で言い切る言い方と、幅を持たせて言う言い方の呼び分け。", "point": "「ちょうど〜」と1つの数字で言うのが点推定。「だいたい〜から〜の間」と幅で言うのが区間推定。", "kid": "点推定は、母集団の値を「これくらい」と1つの数字でズバッと言い当てる言い方。区間推定は、「このくらいからこのくらいの間」と幅を持たせて言う言い方。", "eg": "天気予報で「明日の最高気温は27度です」と言い切るのが点推定。「25度から29度くらいでしょう」と幅で言うのが区間推定。幅で言ったほうが外れにくい。", "viz": "<svg viewBox=\"0 0 340 142\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"30\" y1=\"46\" x2=\"310\" y2=\"46\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><polygon points=\"170,34 163,50 177,50\" fill=\"#3b82f6\"/><text x=\"170\" y=\"24\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">点推定：ちょうど62点</text><line x1=\"30\" y1=\"102\" x2=\"310\" y2=\"102\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"120\" y1=\"94\" x2=\"120\" y2=\"110\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"220\" y1=\"94\" x2=\"220\" y2=\"110\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"120\" y1=\"102\" x2=\"220\" y2=\"102\" stroke=\"#60a5fa\" stroke-width=\"3\"/><text x=\"170.0\" y=\"84\" fill=\"#60a5fa\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">区間推定：58〜66点の間</text><text x=\"170.0\" y=\"128\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">「だいたいこの幅に入る」と考える</text></svg>", "terms": [["点推定", "母集団の値を1つの数字でそのまま見積もる推定のしかた"], ["区間推定", "母集団の値がこのあたりに入るだろうという幅で見積もる推定のしかた"]], "think": "標本から計算した平均（標本平均）は、標本誤差があるぶん、母集団の真の値とぴったり一致するとは限らない。それなのに「ちょうど6.5時間」と1つの数字だけ言い切ると、そのずれの存在が伝わらない。そこで標準誤差の大きさをもとに「だいたいこのあたりに真の値がありそうだ」という幅を添えて伝えるのが区間推定で、標本誤差があることを最初から織り込んだ、より正直な言い方になる。", "vs": "点推定は分かりやすいが、外れたときにどれくらい外れたのか分からない。区間推定は幅があるぶん少し複雑だが、どれくらい自信を持って言えるかまで一緒に伝えられる。", "why_asked": "「6.5時間」という数字だけを見て、あたかも寸分違わぬ真実であるかのように受け取ってしまう誤解を防ぐために区間推定という言い方が使われる。次に習う信頼区間は、この区間推定を具体的な数字の幅として計算したもの。", "usecase": "天気予報の気温の幅、選挙報道の「〜議席から〜議席」という予測、新薬の効果を「〜%から〜%改善」と幅で報告する場面。", "opt": ["正解。「6.2〜6.8時間の間」のように、母集団の値がこのあたりに入るだろうという幅で見積もる言い方が区間推定。", "点推定は「ちょうど6.5時間」のように、1つの数字でズバッと見積もる言い方で、幅は持たせない。", "標準誤差は標本平均がどれくらいばらつきやすいかを表す数字で、幅を持たせた言い方そのものの名前ではない。", "標本誤差は標本ごとの結果のずれのことで、幅を持たせた言い方の名前ではない。"]}'),

  ('stats3-q08', '推測統計',
   '同じやり方で標本調査を20回繰り返し、そのたびに「95%信頼区間」を計算して20本の横棒として書いた。この時、20本のうちだいたい何本くらいが、母集団の本当の値をまたぐと考えられる？',
   NULL::text,
   '["だいたい19本", "ちょうど20本すべて", "だいたい10本", "だいたい1本"]',
   0, '[0]', 'single',
   '{"asked": "95%信頼区間という数字が、本当は何を保証しているのか。", "point": "95%信頼区間の95%は、1回の区間が当たる確率ではなく、この作り方で区間を作り続けたら、だいたい95%の区間が真の値をまたぐという意味。", "kid": "95%信頼区間は、「この計算のやり方で幅を作れば、100回のうちだいたい95回は、その幅の中に本当の値が入りますよ」という、作り方の当たりやすさを表す数字。1本1本の区間が「95%の確率で当たっている」という意味ではない。", "eg": "輪投げで、同じ実力の人が20回輪を投げて、だいたい19回は棒に入るくらいの腕前だとする。すでに投げ終わった1本1本の輪について、あとから「これは95%の確率で入っている」とは言えない。もう入ったか外れたかは決まっている。「この投げ方なら19本くらいは入る腕前だ」というのが95%の意味。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"170\" y1=\"8\" x2=\"170\" y2=\"126\" stroke=\"#c9a04a\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/><text x=\"170\" y=\"138\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">母集団の真の値</text><line x1=\"132\" y1=\"10.0\" x2=\"208\" y2=\"10.0\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"132\" y1=\"15.8\" x2=\"196\" y2=\"15.8\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"133\" y1=\"21.6\" x2=\"213\" y2=\"21.6\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"136\" y1=\"27.4\" x2=\"194\" y2=\"27.4\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"137\" y1=\"33.2\" x2=\"197\" y2=\"33.2\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"129\" y1=\"39.0\" x2=\"219\" y2=\"39.0\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"143\" y1=\"44.8\" x2=\"205\" y2=\"44.8\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"134\" y1=\"50.6\" x2=\"212\" y2=\"50.6\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"118\" y1=\"56.4\" x2=\"210\" y2=\"56.4\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"144\" y1=\"62.2\" x2=\"202\" y2=\"62.2\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"129\" y1=\"68.0\" x2=\"217\" y2=\"68.0\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"136\" y1=\"73.8\" x2=\"204\" y2=\"73.8\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"135\" y1=\"79.6\" x2=\"193\" y2=\"79.6\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"100\" y1=\"85.4\" x2=\"160\" y2=\"85.4\" stroke=\"#c47070\" stroke-width=\"2\"/><line x1=\"126\" y1=\"91.2\" x2=\"208\" y2=\"91.2\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"123\" y1=\"97.0\" x2=\"205\" y2=\"97.0\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"142\" y1=\"102.8\" x2=\"202\" y2=\"102.8\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"131\" y1=\"108.6\" x2=\"201\" y2=\"108.6\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"138\" y1=\"114.4\" x2=\"198\" y2=\"114.4\" stroke=\"#6ab08d\" stroke-width=\"2\"/><line x1=\"125\" y1=\"120.2\" x2=\"215\" y2=\"120.2\" stroke=\"#6ab08d\" stroke-width=\"2\"/><text x=\"170\" y=\"4\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">95%信頼区間を20回作った</text></svg>", "terms": [["信頼区間", "標本から計算した、母集団の真の値がこのあたりにありそうだという幅"], ["信頼水準", "その区間の作り方がどれくらいの割合で真の値をまたぐように設計されているかを表す割合。ここでは95%"]], "think": "20回の標本調査それぞれで、標本平均も標準誤差も少しずつ違う値になる（標本誤差）。その標本ごとに95%信頼区間を計算すると、20本の幅もそれぞれ位置や広さが少しずつ違う横棒になる。「95%」という数字は、この作り方を採用して区間を作り続けたときに、真の値をまたぐ本数の割合がだいたい95%になる、という長い目で見た的中率を表している。だから20本なら、だいたい19本がまたぎ、1本くらい外れても不思議ではない。", "vs": "「この区間に真の値がある確率は95%」という言い方は、実はよくある誤解。真の値は動かない1つの数字で、確率で揺れているのはむしろ標本のほうから作られる区間の位置。95%はあくまで作り方の的中率を表す数字。", "why_asked": "信頼区間は入試にもニュースにもよく出る言葉なのに、「95%の確率で入っている区間」という誤解がとても広まっている。この誤解を正しく直せるかどうかが、統計を分かっているかの分かれ目になる。", "usecase": "選挙報道の「支持率40%（信頼区間37〜43%）」という表記、新薬の効果を「効果量〜（95%信頼区間〜から〜）」と報告する医学論文の定番の書き方。", "opt": ["正解。95%信頼区間の作り方で20本の区間を作れば、そのうちだいたい19本くらいが真の値をまたぐと期待できる。", "20本すべてがまたぐとは限らない。95%という数字は、当たらない区間も一定の割合（だいたい5%）で出ることを織り込んだ数字。", "だいたい10本しかまたがないのは50%程度の信頼区間の話で、95%信頼区間としてはまたぐ本数が少なすぎる。", "だいたい1本しかまたがないのは信頼区間がほとんど機能していない状態で、95%信頼区間の的中率とはかけ離れている。"]}'),

  ('stats3-q09', '推測統計',
   '標本から分散を計算するとき、多くの教科書では「データの個数（n）」ではなく「データの個数から1を引いた数（n-1）」で割ると教わる。なぜnではなくn-1で割るのか？',
   NULL::text,
   '["標本平均を使うと分散が小さめに出る癖があり、その分を補正するため", "n-1で割ったほうが計算がシンプルになるという、昔からの単なる慣習だから", "標本の人数を必ず1人分減らして数える決まりになっているから", "母集団の分散を実際より大きく見積もらせるため"]',
   0, '[0]', 'single',
   '{"asked": "標本の分散をn-1で割る理由。", "point": "標本平均を使って計算したばらつきは、真の平均を使うときよりわずかに小さめに出る癖がある。n-1で割ることでその小さめの癖を補正し、母集団の分散をちょうどよく見積もれるようにしている。", "kid": "標本から分散を計算するとき、母集団の本当の平均ではなく、標本自身から計算した平均（標本平均）を使う。この標本平均は、その標本のデータに一番近くなるように選ばれた数字なので、そこからの散らばりを測ると、本当の散らばりよりわずかに小さく出てしまう癖がある。n-1で割ることで、この小さく出る分をちょうど埋め合わせている。", "eg": "5人の体重の「真ん中の重さ」を、本当の日本人全体の平均ではなく、その5人自身のちょうど真ん中に合わせて選んだとする。すると当然、その5人はその真ん中の重さに近くなるように見える。物差しを、測る対象自身に合わせて作ってしまうと、実際より小さく測れてしまうのと同じ理屈。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"20\" y=\"20\" width=\"130\" height=\"42\" rx=\"8\" fill=\"none\" stroke=\"#c47070\"/><text x=\"85\" y=\"38\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">偏差の2乗和 ÷ n</text><text x=\"85\" y=\"54\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">→ 少し小さめに出る癖</text><line x1=\"150\" y1=\"41\" x2=\"190\" y2=\"41\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"190,41 185.7,43.6 185.7,38.4\" fill=\"#3b82f6\"/><text x=\"170\" y=\"30\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">n-1に</text><rect x=\"192\" y=\"20\" width=\"130\" height=\"42\" rx=\"8\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"257\" y=\"38\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">偏差の2乗和 ÷ (n-1)</text><text x=\"257\" y=\"54\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">→ ちょうどよい大きさに補正</text><text x=\"170\" y=\"88\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">標本平均はその標本自身に近づくよう選ばれているので、</text><text x=\"170\" y=\"102\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">そこからの散らばりは本当より小さく出やすい</text><text x=\"170\" y=\"122\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">n-1で割ることで、その小さめの癖をちょうど打ち消す</text></svg>", "terms": [["標本平均", "標本（手元のデータ）だけから計算した平均。母集団の本当の平均とは少し違うことがある"], ["不偏推定量", "標本から計算しても、平均するとちょうど母集団の本当の値に一致するように作られた計算式"], ["n-1（自由度）", "割り算に使う数を、データの個数より1つ少なくすること"]], "think": "なぜn-1で割ると本当に補正になるのかがカギ。分散の計算では、1人1人の値から平均を引いた差（偏差）を2乗して足し合わせる。母集団の本当の平均を使えるなら話は単純だが、標本しか手元にないときは、代わりに標本平均を使うしかない。標本平均は、その標本のデータに一番よくフィットするように計算された数字なので、標本の中のデータは、本当の平均から測るときよりも、標本平均からのほうが必ず少し近くなってしまう。つまり標本平均を使って計算した偏差の2乗和は、本当は少し小さめに出る。そこでnより1小さいn-1で割ることで、割る数を小さくして計算結果を少し大きめに押し上げ、平均すると母集団の本当の分散にちょうど一致するように帳尻を合わせている。", "vs": "nで割った値は、この標本の中でのばらつきを表すには問題ないが、母集団のばらつきの見積もりとして使うと平均的に小さめに偏る。n-1で割った値は、母集団のばらつきの見積もりとして、平均的に偏りがない（不偏）という保証がある点が違う。", "why_asked": "標本から母集団のばらつきを見積もる場面は、標準誤差や信頼区間など、この先ずっと出てくる計算の土台になる。ここでnとn-1のどちらを使うかを取り違えると、その先の計算がすべて少しずつ狂ってしまう。", "usecase": "統計ソフトやExcelの分散関数（標本の分散用の関数）は、標準でn-1で割る式が使われている。母集団の一部の標本から品質のばらつきを見積もる品質管理の現場でも、この補正が使われている。", "opt": ["正解。標本平均を使って計算するとばらつきが小さめに出る癖があり、n-1で割ることでその癖をちょうど補正できる。", "n-1という数はこの補正の仕組みから理由があって決まっており、単なる慣習や覚えやすさのための決まりではない。", "n-1で割るのは人数を実際に1人減らして考えているのではなく、割り算に使う数を1つ小さくしているだけで、標本の中身は変わらない。", "n-1で割るのは母集団の分散を実際より大きく見せるためではなく、小さめに出る癖をちょうど打ち消して正しい大きさに近づけるため。"]}'),

  ('stats3-q10', '推測統計',
   'ある調査で100人に聞いたところ、結果の誤差（標準誤差）は±4%だった。同じ誤差を半分の±2%まで小さくしたい場合、何人くらいに聞けばよいと考えられる？',
   NULL::text,
   '["だいたい400人", "だいたい200人", "だいたい150人", "だいたい250人"]',
   0, '[0]', 'single',
   '{"asked": "調査の誤差を小さくするために必要な人数の増やし方。", "point": "誤差（標準誤差）は標本の大きさの平方根に反比例する。誤差を半分にしたいなら、人数は4倍（2の2乗）必要になる。", "kid": "調査の誤差は、人数を増やすほど小さくなるが、人数を2倍にしても誤差は半分にはならない。誤差をきっちり半分にしたいなら、人数を4倍に増やす必要がある。", "eg": "写真をきれいにするのにピクセル数を増やすようなもの。ぼやけ具合（誤差）を半分にするには、ピクセル数（人数）を少し増やすだけでは足りず、ぐっと多く増やす必要がある。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"34\" y1=\"20\" x2=\"34\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"34\" y1=\"118\" x2=\"316\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><text x=\"20\" y=\"24\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">誤差</text><text x=\"316\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">人数(n)</text><path d=\"M40 30 Q90 60 130 78 Q200 96 310 110\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><circle cx=\"100\" cy=\"82\" r=\"4.5\" fill=\"#3b82f6\"/><text x=\"100\" y=\"70\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">100人：誤差 ±4%</text><circle cx=\"250\" cy=\"100\" r=\"4.5\" fill=\"#6ab08d\"/><text x=\"250\" y=\"88\" fill=\"#6ab08d\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">400人：誤差 ±2%</text><text x=\"175\" y=\"20\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">人数を4倍にしないと誤差は半分にならない</text></svg>", "terms": [["標準誤差", "標本平均が母集団の真の値からどれくらいばらつきやすいかを表す数字。標本の大きさが増えるほど小さくなる"], ["標本の大きさ（n）", "標本調査で集めたデータの個数。ここでは調査した人数"]], "think": "標準誤差は、母集団の標準偏差を標本の大きさ（n）の平方根（√n）で割って計算される。√nを2倍にするには、nそのものは2×2で4倍にしないといけない（√400=20は√100=10のちょうど2倍）。標準誤差は√nで割った値なので、√nが2倍になれば標準誤差は半分になる。つまり誤差を半分にしたいなら、100人の4倍である400人くらいが必要になる。", "vs": "「誤差を半分にしたいから人数も2倍でよい」は、この分野で一番ありがちな早とちり。誤差は人数そのものではなく、人数の平方根に反比例して縮むので、必要な人数は思っている以上に増える。", "why_asked": "調査や実験の計画を立てる人は、どれくらいの精度がほしいかから何人集めればよいかを逆算する必要がある。この√nの関係を知らないと、予算や時間の見積もりを大きく間違える。", "usecase": "世論調査で誤差を±1%まで詰めたいときの必要サンプル数の見積もり、新薬の臨床試験で効果の差を検出するために必要な被験者数の設計。", "opt": ["正解。誤差は人数の平方根に反比例して縮むので、誤差を半分にするには人数を4倍（100人の4倍で400人）にする必要がある。", "だいたい200人（2倍）では、平方根の関係から誤差はおよそ0.71倍にしか縮まらず、半分の±2%までは届かない。", "だいたい150人（1.5倍）でも誤差は少し縮むが、200人や250人ほどには縮まらず、目標の半分にはまだ遠い。", "だいたい250人（2.5倍）でも、誤差はおよそ0.63倍程度にしか縮まらず、目標の半分には足りない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
